function choiceTask(host,task,cfg={}){
  let locked=false,helped=false,answered=false,helpTimer=null,gated=!!cfg.gated;
  host.dataset.task=task.id||'';host.__task=task;
  host.innerHTML=`<div class="task-card"><div class="mini-label">${cfg.label||'Practice'}</div><div class="task-title">${task.title}</div><div class="audio-line"><button class="speaker task-play" aria-label="Play audio"></button><div class="caption task-caption">${task.caption||''}</div></div><div class="options"></div><div class="feedback" aria-live="polite"></div><div class="row next-row"></div></div>`;
  const opts=host.querySelector('.options'),feedback=host.querySelector('.feedback'),nextRow=host.querySelector('.next-row');
  host.querySelector('.task-play').onclick=()=>play(task.audio);
  shuffle(task.options).forEach(o=>{const b=document.createElement('button');b.className='choice';b.dataset.id=o.id;b.disabled=gated;b.innerHTML=(o.img?`<img src="${A}${o.img}" alt="">`:'')+(o.text?`<span>${o.text}</span>`:'');b.onclick=()=>{
    if(gated||locked||answered)return;const correct=o.id===task.answer;
    if(!correct&&cfg.retry){b.classList.add('wrong');sfx('sfx_wrong.mp3');feedback.textContent='Listen and try again.';later(()=>b.classList.remove('wrong'),450);return;}
    locked=true;answered=true;opts.querySelectorAll('button').forEach(x=>x.disabled=true);b.classList.add(correct?'correct':'wrong');
    if(!correct){const right=[...opts.querySelectorAll('button')].find(x=>x.dataset.id===task.answer);if(right)right.classList.add('correct');}
    sfx(correct?'sfx_correct.mp3':'sfx_wrong.mp3');feedback.textContent=correct?'Correct. Say the complete answer aloud.':'Not yet. Look at the correct answer; a new item will follow.';
    if(task.heard)host.querySelector('.task-caption').textContent='You heard: '+task.heard;cfg.onAnswer&&cfg.onAnswer({correct,helped,task});
    if(cfg.next!==false){const n=document.createElement('button');n.className='action amber';n.textContent=cfg.nextLabel||'Next question';n.onclick=()=>{stopAudio();cfg.onNext&&cfg.onNext({correct,helped,task});};nextRow.appendChild(n);}
  };opts.appendChild(b);});
  return{unlock(){gated=false;opts.querySelectorAll('button').forEach(x=>x.disabled=false);}};
}

function teacherObservation(host,cfg){
  let attempted=false,helped=false,recorded=false,helpTimer=null;
  host.innerHTML=`<div class="task-card"><div class="mini-label">${cfg.label||'Teacher observation'}</div><div class="task-title">${cfg.title}</div>${cfg.audio?`<div class="audio-line"><button class="speaker obs-play" aria-label="Play prompt"></button><div class="caption">${cfg.caption||'Listen, then respond aloud.'}</div></div>`:''}${cfg.image?`<img class="pic" src="${A}${cfg.image}" style="height:170px;display:block;margin:4px auto">`:''}${cfg.extra||''}<div class="answer-box">No answer shown. Student speaks first.</div><div class="row"><button class="action obs-tried">Student tried</button><button class="action secondary obs-help" disabled>Help · first words</button>${cfg.model?'<button class="action secondary obs-model" disabled>Model</button><button class="action amber obs-hide" disabled>Hide model</button>':''}</div><div class="observation"><div class="mini-label">Teacher listens, then records what happened</div><div class="row" style="margin-top:8px"><button class="action green obs-independent" disabled>Independent response heard</button><button class="action secondary obs-support" disabled>Support needed</button></div></div></div>`;
  const answer=host.querySelector('.answer-box'),tried=host.querySelector('.obs-tried'),help=host.querySelector('.obs-help'),independent=host.querySelector('.obs-independent'),support=host.querySelector('.obs-support');
  const model=host.querySelector('.obs-model'),hide=host.querySelector('.obs-hide');if(cfg.audio)host.querySelector('.obs-play').onclick=()=>play(cfg.audio);
  tried.onclick=()=>{attempted=true;tried.disabled=true;help.disabled=!cfg.hint;independent.disabled=false;support.disabled=false;if(model)model.disabled=false;};
  help.onclick=()=>{if(!attempted||recorded)return;helped=true;independent.disabled=true;answer.innerHTML=`<span class="help-flash">${cfg.hint}</span>`;clearTimeout(helpTimer);helpTimer=setTimeout(()=>{answer.textContent='Help hidden. Try again without the words.';},5000);};
  if(model)model.onclick=()=>{if(!attempted)return;helped=true;independent.disabled=true;answer.textContent=cfg.model;play(cfg.modelAudio);hide.disabled=false;};
  if(hide)hide.onclick=()=>{stopAudio();answer.textContent='Model hidden. Say it again.';hide.disabled=true;model.disabled=true;};
  function observe(isIndependent){if(!attempted||recorded||(helped&&isIndependent))return;recorded=true;independent.disabled=true;support.disabled=true;help.disabled=true;if(model)model.disabled=true;if(hide)hide.disabled=true;cfg.onObserve&&cfg.onObserve({independent:isIndependent,helped});}
  independent.onclick=()=>observe(true);support.onclick=()=>observe(false);
}

const screensHost=$('#screens'),screens=[];
const TEACHER_GUIDES=[
'<b>Set up (under 1 min):</b> Tap sound check. Confirm microphone, camera and network. Keep paper optional; no teaching here.',
'<b>Warm-up (1.5 min):</b> Read only this device’s L5 record. Failed stations come first; without a record, two random items appear. Activate, do not reteach.',
'<b>Map (30 sec):</b> Name the six challenges. Good-bye / See you is a WC1 transfer item, not a new Unit 1 goal.',
'<b>Model 1 (1 min):</b> Play the five Talk Time turns in order. Student only watches and points to A or B. Then model “I’m third!” once.',
'<b>Model 2 (1 min):</b> Play the official clap verse and official feelings question/answer. Student watches the whole model; no independent claim yet.',
'<b>Model 3 (45 sec):</b> Contrast cap/cape. Model Good-bye / See you as old knowledge. Keep this brief.',
'<b>Guided dialogue (2 min):</b> Teacher takes A; student takes B. All five frames stay visible. Build only where the student stops. This is guided completion, not independent mastery.',
'<b>Guided numbers (1 min):</b> Choose third, then fifth. Student tries before Model. Accept understandable ordinal pronunciation; do not drill /θ/ beyond 30 seconds.',
'<b>Guided chant + correction (1.5 min):</b> Sing the clap verse with the visible frame, then correct F aloud. Keep the complete correction frame available.',
'<b>Guided feelings (1.5 min):</b> Student first asks YOU “What’s the matter?”, then answers from the picture. Listen for the ’s and I’m.',
'<b>Show Rush (2 min):</b> Eight mixed items. For oral items, record only what you actually hear. For objective items, one locked answer then Next. Accuracy before speed.',
'<b>Check 1③ (1 min):</b> No sentence frame. Student chants the keywords, then corrects the false ordinal statement. Model is available only after an attempt; using it means support, not independent.',
'<b>Check 1④ (1 min):</b> Student actively asks What’s the matter?, then answers from the picture. No Arabic or answer text. Help gives first words only and hides after five seconds.',
'<b>Check 1⑤ (1 min):</b> Four whole-word listening items. No Arabic or Model. Three first-try correct answers are needed for independent evidence.',
'<b>Repair + Check 2 (4 min):</b> Repair only failed Check 1 items. Follow Meaning → Slow → Contrast → Model → Build → Hide help → Try again. Final Show stays locked until every failed item has a Check 2 record.',
'<b>Final Show (3 min):</b> Six beats in order. Answers start hidden. Help gives first words for five seconds. Record independent or helped from real performance; one error does not stop the show. Goal: at least four independent items.',
'<b>School interface (45 sec):</b> One What’s the matter? listening-choice item. Temporary H5 imitation pending the current 1448 Workbook.',
'<b>School interface (45 sec):</b> One sound-discrimination item. The weaker class is selected from local evidence when available; the teacher may switch groups. Temporary H5 imitation.',
'<b>Evidence (30 sec):</b> Read the six actual Final Show records. Not done, helped and independent are different. Never say “all mastered” from navigation alone.',
'<b>Exit (30 sec):</b> Family performance is voluntary; a 30-second home video is only a suggestion. Open Review or show the QR. No classroom recording is required.'
];
function addScreen(objective,html,init){const el=document.createElement('section');el.className='screen';el.innerHTML=html;screensHost.appendChild(el);const api=init?(init(el)||{}):{};screens.push({objective,el,onEnter:api.onEnter,onLeave:api.onLeave});}
let cur=0;
function show(i){i=Math.max(0,Math.min(screens.length-1,i));if(screens[cur]&&screens[cur].onLeave)screens[cur].onLeave();navToken++;stopAudio();clearTimeout(toastTimer);$('#toast').classList.remove('show');cur=i;screens.forEach((s,k)=>s.el.classList.toggle('active',k===i));$('#objective').textContent=screens[i].objective;$('#teacher-copy').innerHTML=TEACHER_GUIDES[i]||'';$('#page-num').textContent=(i+1)+' / '+screens.length;$('#progress').style.width=((i+1)/screens.length*100)+'%';$('#btn-prev').disabled=i===0;$('#btn-next').disabled=i===screens.length-1;document.querySelectorAll('#thumbs button[data-page]').forEach((b,k)=>b.classList.toggle('cur',k===i));if(screens[i].onEnter)screens[i].onEnter();}
function fit(){const s=Math.min(window.innerWidth/1280,window.innerHeight/720);$('#stage').style.transform='scale('+s+')';}
window.addEventListener('resize',fit);
(function(){const w=$('#watermark');for(let y=0;y<5;y++)for(let x=0;x<4;x++){const sp=document.createElement('span');sp.textContent='khusoosi · خصوصي';sp.style.left=(x*340+(y%2)*120)+'px';sp.style.top=(y*150+20)+'px';w.appendChild(sp);}})();
$('#btn-ar').onclick=()=>{const on=document.body.classList.toggle('ar-on');$('#btn-ar').setAttribute('aria-pressed',on);};
$('#btn-teacher').onclick=()=>{const on=document.body.classList.toggle('teacher-on');$('#btn-teacher').setAttribute('aria-pressed',on);};
$('#btn-prev').onclick=()=>show(cur-1);$('#btn-next').onclick=()=>show(cur+1);$('#btn-thumbs').onclick=()=>$('#thumbs').classList.toggle('open');
$('#btn-fs').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen().catch(()=>{});
document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(cur+1);if(e.key==='ArrowLeft')show(cur-1);});
screensHost.addEventListener('click',e=>{const b=e.target.closest('[data-audio]');if(b)play(b.dataset.audio);});
const ICONS={mic:'<svg viewBox="0 0 24 24" width="34" height="34" fill="#6a4fa3"><path d="M12 15a3 3 0 0 0 3-3V6a3 3 0 1 0-6 0v6a3 3 0 0 0 3 3zm6-3a6 6 0 0 1-12 0H4a8 8 0 0 0 7 7.94V22h2v-2.06A8 8 0 0 0 20 12h-2z"/></svg>',cam:'<svg viewBox="0 0 24 24" width="34" height="34" fill="#6a4fa3"><path d="M17 10.5V7a1 1 0 0 0-1-1H4a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-3.5l4 4v-11l-4 4z"/></svg>',net:'<svg viewBox="0 0 24 24" width="34" height="34" fill="#6a4fa3"><path d="M12 21l3.5-4.5a5 5 0 0 0-7 0L12 21zm0-18C7.4 3 3.2 4.7 0 7.4l2 2.4A15.9 15.9 0 0 1 12 6c3.9 0 7.4 1.5 10 3.8l2-2.4C20.8 4.7 16.6 3 12 3zm0 6c-3 0-5.8 1.1-7.9 3l2 2.4A8.9 8.9 0 0 1 12 12c2.3 0 4.4.8 6 2.2l1.9-2.4A11.9 11.9 0 0 0 12 9z"/></svg>',pen:'<svg viewBox="0 0 24 24" width="34" height="34" fill="#6a4fa3"><path d="M3 17.2V21h3.8L17.9 9.9l-3.8-3.8L3 17.2zM20.7 7a1 1 0 0 0 0-1.4l-2.3-2.3a1 1 0 0 0-1.4 0l-1.8 1.8 3.8 3.8 1.7-1.9z"/></svg>'};
const TALK=[['a_official_tt1.mp3',"Hi. It's nice to meet you."],['a_official_tt2.mp3',"It's nice to meet you, too."],['a_official_tt3.mp3','Hi. How are you?'],['a_official_tt4.mp3',"I'm great, thanks. And you?"],['a_official_tt5.mp3',"I'm fine."]];
const CHECK_KEYS=['chant','feelings','sounds'];
function check1Complete(){return CHECK_KEYS.every(k=>state.check1[k]);}
function failedChecks(){return CHECK_KEYS.filter(k=>state.check1[k]&&!state.check1[k].firstTry);}
function finalUnlocked(){return check1Complete()&&failedChecks().every(k=>state.check2[k]&&state.check2[k].done);}
window.__finalUnlocked=finalUnlocked;

/* S1 */
addScreen('Class setup',`<div style="direction:rtl;text-align:center;width:100%"><h1 style="font-size:42px;color:#463a5e;margin-bottom:24px">قبل أن نبدأ الدرس</h1><div class="grid2" style="max-width:900px;margin:0 auto 24px">${[['mic','افتح الميكروفون والكاميرا'],['net','تأكد أن الإنترنت يعمل بشكل جيد'],['cam','اجلس في مكان هادئ ومريح'],['pen','جهّز الورقة والقلم']].map(([k,t])=>`<div class="card" style="display:flex;align-items:center;gap:16px;padding:17px 22px">${ICONS[k]}<span style="font-size:23px;font-weight:700;color:#544867">${t}</span></div>`).join('')}</div><button id="soundcheck" class="speaker"></button><div id="soundcheck-label" style="font-size:20px;color:#76582b;margin-top:10px;font-weight:700">اضغط لاختبار الصوت</div><div dir="ltr" style="font-size:15px;color:#6f6680;margin-top:6px">Hello! Can you hear me?</div></div>`,el=>({onEnter(){const b=el.querySelector('#soundcheck'),label=el.querySelector('#soundcheck-label');b.onclick=()=>{label.textContent='… استمع';play('a_t_soundcheck.mp3',()=>{b.style.backgroundColor='#24a66a';label.textContent='الصوت يعمل ✓';});};}}));

/* S2 */
addScreen('Warm-up · local L5 evidence',`<div class="wrap"><span class="tag">WARM-UP · THIS DEVICE ONLY</span><div class="lead">Two quick answers. Ready?</div><div id="warm-status" class="mini-label"></div><div id="warm-task"></div></div>`,el=>{let deck=[],i=0;function paint(){if(i>=deck.length){el.querySelector('#warm-task').innerHTML='<div class="task-card"><div class="lead">Warm-up complete.</div><div class="sub">Now six challenges.</div></div>';return;}choiceTask(el.querySelector('#warm-task'),TASKS[deck[i]],{label:'Quick '+(i+1)+' / 2',onNext:()=>{i++;paint();}});}return{onEnter(){const previous=readJSON('khusoosi:wc2-u1-l5:progress',null),checks=previous&&previous.check1||{};const map={greeting:'greetHow',ordinal:'ordinalF',feelings:'feelCold',sounds:'soundcape'};const weak=Object.keys(map).filter(k=>checks[k]&&!checks[k].firstTry).map(k=>map[k]);deck=weak.length?weak.slice(0,2):shuffle(['greetNice','ordinalF','feelCold','soundcape']).slice(0,2);while(deck.length<2){const extra=['greetNice','feelCold','soundcape'].find(x=>!deck.includes(x));deck.push(extra);}el.querySelector('#warm-status').textContent=weak.length?'L5 local record: needs-practice items come first.':'No usable L5 local record: mixed random warm-up.';i=0;paint();}};});

/* S3 */
addScreen('Today · six challenges',`<div class="wrap"><span class="tag">NEW FRIEND CHALLENGE SHOW</span><div class="lead">Six things. First with me, then by yourself.</div><div class="sub">Final goal: at least 4 independent challenges.</div><div class="grid6">${[['1','Talk','Five-turn first meeting.'],['2','Number','Say your given place.'],['3','Chant','Sing keywords. Fix a mistake.'],['4','Feelings','Ask and answer.'],['5','Sounds','Four words: at least 3 correct.'],['6','Good-bye','Good-bye. See you. · WC1 transfer']].map(([n,t,p])=>`<div class="task-card challenge-card"><div class="num">CHALLENGE ${n}</div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div>`);

/* S4 */
addScreen('Model 1 · talk + number',`<div class="wide grid2" style="grid-template-columns:1.25fr .75fr;align-items:start"><div class="task-card"><span class="tag">WATCH · FIVE TURNS</span><div class="dialogue" style="margin-top:12px">${TALK.map(([au,t],i)=>`<button class="speaker" data-audio="${au}"></button><div class="line ${i%2?'role-b':'role-a'}">${i%2?'B':'A'} · ${t}</div>`).join('')}</div></div><div class="task-card"><span class="tag">WATCH · GIVEN PLACE</span><img class="pic" src="${A}sec_queue.png" style="height:220px;width:100%"><div class="audio-line"><button class="speaker" data-audio="a_t_third.mp3"></button><div class="caption">I'm third!</div></div><div class="sub">Point to the speaker. Do not repeat yet.</div></div></div>`);

/* S5 */
addScreen('Model 2 · chant + feelings',`<div class="wide grid2" style="align-items:start"><div class="task-card"><span class="tag">OFFICIAL CHANT · CLAP VERSE</span><img class="pic" src="${A}l2_chant_girl.jpg" style="height:230px;width:100%"><div class="audio-line"><button class="speaker" data-audio="a_official_chant_clap.mp3"></button><div class="caption">If you're happy … clap your hands.</div></div><div class="sub">Watch. Join only if you already can.</div></div><div class="task-card"><span class="tag">OFFICIAL FEELINGS · QUESTION + ANSWER</span><img class="pic" src="${A}ft_hungry.jpg" style="height:230px;width:100%"><div class="audio-line"><button class="speaker small" data-audio="a_official_wtm.mp3"></button><div class="caption">What's the matter?</div></div><div class="audio-line"><button class="speaker small" data-audio="a_official_ans_hungry.mp3"></button><div class="caption">I'm hungry.</div></div></div></div>`);

/* S6 */
addScreen('Model 3 · sounds + good-bye',`<div class="wide grid2" style="align-items:start"><div class="task-card"><span class="tag">SHORT ↔ LONG</span><div class="grid2">${['cap','cape'].map(w=>`<div><img class="pic" src="${A}${WORDS[w].img}" style="height:170px;width:100%"><div class="audio-line"><button class="speaker small" data-audio="${WORDS[w].audio}"></button><div class="caption">${w} · ${WORDS[w].cls==='a'?'short a':'long a_e'}</div></div></div>`).join('')}</div></div><div class="task-card"><span class="tag">WC1 TRANSFER · NOT A NEW GOAL</span><img class="pic" src="${A}wc2_talk_a.png" style="height:220px;width:100%"><div class="audio-line"><button class="speaker" data-audio="a_t_goodbye_seeyou.mp3"></button><div class="caption">Good-bye. See you.</div></div><div class="sub">One friendly ending.</div></div></div>`);

/* S7 */
addScreen('Guided Show · five-turn talk',`<div class="wide grid2" style="grid-template-columns:270px 1fr;align-items:center"><div><img class="pic" src="${A}wc2_talk_b.png" style="width:100%;height:350px"><div class="book-ref">Student Book · Unit 1 · Talk Time</div></div><div class="task-card"><span class="tag">GUIDED · FRAMES STAY VISIBLE</span><div class="sub">Teacher = A · Student = B</div>${TALK.map(([au,t],i)=>`<div class="frame ${i%2?'role-b':'role-a'}" style="margin:6px 0;display:flex;align-items:center;gap:10px"><button class="speaker small" data-audio="${au}"></button><span>${i%2?'B':'A'} · ${t}</span></div>`).join('')}<button id="guided-talk-done" class="action green" style="margin-top:8px">Guided round complete</button><div id="guided-talk-feedback" class="feedback"></div></div></div>`,el=>({onEnter(){const b=el.querySelector('#guided-talk-done');b.onclick=()=>{el.querySelector('#guided-talk-feedback').textContent='Guided round recorded. Independence is checked later.';sfx('sfx_success.mp3');};}}));

/* S8 */
addScreen('Guided Show · given place',`<div class="wrap"><span class="tag">GUIDED · TRY BEFORE MODEL</span><div class="lead">Your teacher gives you a place.</div><img class="pic" src="${A}sec_queue.png" style="height:220px"><div class="row"><button class="action secondary ord-target" data-word="third">Teacher: third</button><button class="action secondary ord-target" data-word="fifth">Teacher: fifth</button></div><div id="ord-frame" class="frame" style="max-width:520px;margin:12px auto">Choose a place. Then say: I'm ___!</div><div class="row"><button id="ord-tried" class="action" disabled>I said it</button><button id="ord-model" class="action secondary" disabled>Model</button><button id="ord-next" class="action amber" disabled>Next place</button></div><div id="ord-feedback" class="feedback"></div></div>`,el=>{let target=null,round=0;return{onEnter(){round=0;target=null;const frame=el.querySelector('#ord-frame'),tried=el.querySelector('#ord-tried'),model=el.querySelector('#ord-model'),next=el.querySelector('#ord-next');el.querySelectorAll('.ord-target').forEach(b=>b.onclick=()=>{target=b.dataset.word;frame.textContent="Say your place: I'm ___!";tried.disabled=false;model.disabled=true;next.disabled=true;el.querySelector('#ord-feedback').textContent='Student tries before the model.';});tried.onclick=()=>{tried.disabled=true;model.disabled=false;next.disabled=false;};model.onclick=()=>{if(!target)return;frame.textContent="I'm "+target+'!';play('a_t_'+target+'.mp3');};next.onclick=()=>{round++;target=null;frame.textContent=round>=2?'Two guided places complete.':"Choose the other place. Say: I'm ___!";tried.disabled=true;model.disabled=true;next.disabled=true;};}};});

/* S9 */
addScreen('Guided Show · chant + correction',`<div class="wide grid2" style="align-items:start"><div class="task-card"><span class="tag">GUIDED CHANT</span><div class="audio-line"><button class="speaker" data-audio="a_official_chant_clap.mp3"></button><div class="caption">Sing the keywords.</div></div><div class="frame">If you're happy and you know it,<br>clap your hands.</div><img class="pic" src="${A}l2_chant_girl.jpg" style="height:170px;width:100%"></div><div class="task-card"><span class="tag">GUIDED CORRECTION</span><div class="audio-line"><button class="speaker" data-audio="a_t_f_seventh.mp3"></button><div class="caption">F is the seventh letter.</div></div><div class="frame">No, it's the sixth letter.</div><button class="action secondary" data-audio="a_t_no_sixth.mp3" style="margin-top:12px">Hear the correction</button><div class="sub" style="margin-top:12px">Say it once with the frame. No long pronunciation drill.</div></div></div>`);

/* S10 */
addScreen('Guided Show · ask + answer',`<div class="wrap"><span class="tag">GUIDED · STUDENT ASKS FIRST</span><div class="lead" id="feel-guide-title">Ask your teacher.</div><div class="grid2" style="align-items:center;max-width:960px;margin:auto"><div class="task-card"><div id="feel-guide-frame" class="frame">What's the matter?</div><button id="feel-guide-model" class="speaker" style="margin-top:14px"></button><div class="sub">Try first. Use Model only if needed.</div></div><img id="feel-guide-img" class="pic" src="${A}wc2_talk_a.png" style="height:280px;width:100%"></div><button id="feel-guide-next" class="action amber">Next: answer from a picture</button></div>`,el=>{let phase=0;return{onEnter(){phase=0;const title=el.querySelector('#feel-guide-title'),frame=el.querySelector('#feel-guide-frame'),img=el.querySelector('#feel-guide-img'),model=el.querySelector('#feel-guide-model'),next=el.querySelector('#feel-guide-next');function paint(){if(phase===0){title.textContent='Ask your teacher.';frame.textContent="What's the matter?";img.src=A+'wc2_talk_a.png';model.onclick=()=>play('a_official_wtm.mp3');next.textContent='Next: answer from a picture';}else{title.textContent='Your teacher asks. You answer.';frame.textContent="I'm cold.";img.src=A+'ft_cold.jpg';model.onclick=()=>play('a_official_ans_cold.mp3');next.textContent='Guided question + answer complete';}}model.disabled=false;next.onclick=()=>{if(phase===0){phase=1;paint();}else{sfx('sfx_success.mp3');toast('Guided round complete. Independence comes next.');}};paint();}};});

/* S11 */
addScreen('Show Rush · eight mixed items',`<div class="wrap"><span class="tag">SHOW RUSH · ACCURACY FIRST</span><div class="lead">Eight challenges. One answer, then Next.</div><div id="rush-task"></div><div id="rush-next" class="row"></div></div>`,el=>{let deck=[],i=0;const oral={talk:{title:'Respond to your new friend.',audio:'a_official_tt1.mp3',caption:"Hi. It's nice to meet you."},ordinal:{title:'Say your given place: third.',image:'sec_queue.png'},chant:{title:'Join the clap verse. Say the keywords.',audio:'a_official_chant_clap.mp3',caption:'No words on screen.'},feel:{title:'Ask your teacher about the feeling.',image:'ft_cold.jpg'}};function advance(){i++;paint();}function paint(){el.querySelector('#rush-next').innerHTML='';if(i>=deck.length){el.querySelector('#rush-task').innerHTML=`<div class="task-card"><div class="lead">Rush complete.</div><div class="sub">${state.rushErrors.length?'Needs-practice items are recorded locally.':'No Rush support recorded.'}</div></div>`;save();return;}const item=deck[i];if(!Object.hasOwn(oral,item)){choiceTask(el.querySelector('#rush-task'),TASKS[item],{label:'Rush '+(i+1)+' / 8',onAnswer:r=>{if(!r.correct&&!state.rushErrors.includes(item))state.rushErrors.push(item);save();},onNext:advance});}else{const o=oral[item];teacherObservation(el.querySelector('#rush-task'),{label:'Rush '+(i+1)+' / 8 · teacher listens',...o,onObserve:r=>{if(!r.independent&&!state.rushErrors.includes(item))state.rushErrors.push(item);save();const n=document.createElement('button');n.className='action amber';n.textContent='Next Rush item';n.onclick=advance;el.querySelector('#rush-next').appendChild(n);}});}}return{onEnter(){deck=shuffle(['talk','ordinal','chant','feel','greetNice','feelCold','soundcape','soundpin']);i=0;state.rushErrors=[];paint();}};});

/* S12 */
addScreen('Check 1③ · chant + ordinal',`<div class="wrap"><span class="tag">CHECK 1③ · NO FRAME · NO ARABIC</span><div class="lead">Chant, then fix the mistake.</div><div id="check-chant"></div></div>`,el=>{let parts={};function paintCorrection(){teacherObservation(el.querySelector('#check-chant'),{label:'Check 1③ · correction',title:'Fix the false statement aloud.',audio:'a_t_f_seventh.mp3',caption:'Listen. Correct it without a sentence frame.',hint:'No …',model:"No, it's the sixth letter.",modelAudio:'a_t_no_sixth.mp3',onObserve:r=>{parts.correction=r.independent;state.check1.chant={firstTry:parts.chant&&parts.correction,parts:{...parts},helped:parts.chantHelp||r.helped};save();toast('Check 1③ recorded.');}});}return{onEnter(){parts={};teacherObservation(el.querySelector('#check-chant'),{label:'Check 1③ · chant',title:'Join the clap verse. Keywords must be heard.',audio:'a_official_chant_clap.mp3',caption:'No lyrics on screen.',hint:"If you're …",model:"If you're happy and you know it, clap your hands.",modelAudio:'a_official_chant_clap.mp3',onObserve:r=>{parts.chant=r.independent;parts.chantHelp=r.helped;paintCorrection();}});}};});

/* S13 */
addScreen('Check 1④ · active question + answer',`<div class="wrap"><span class="tag">CHECK 1④ · NO ARABIC · NO ANSWER</span><div class="lead">You ask. Then you answer.</div><div id="check-feelings"></div></div>`,el=>{let parts={};function paintAnswer(){teacherObservation(el.querySelector('#check-feelings'),{label:'Check 1④ · answer',title:'Your teacher asks. Answer from the picture.',image:'ft_cold.jpg',hint:"I'm …",model:"I'm cold.",modelAudio:'a_official_ans_cold.mp3',onObserve:r=>{parts.answer=r.independent;state.check1.feelings={firstTry:parts.ask&&parts.answer,parts:{...parts},helped:parts.askHelp||r.helped};save();toast('Check 1④ recorded.');}});}return{onEnter(){parts={};teacherObservation(el.querySelector('#check-feelings'),{label:'Check 1④ · active question',title:'Ask your teacher about the feeling.',image:'wc2_talk_a.png',hint:"What's …",model:"What's the matter?",modelAudio:'a_official_wtm.mp3',onObserve:r=>{parts.ask=r.independent;parts.askHelp=r.helped;paintAnswer();}});}};});

/* S14 */
addScreen('Check 1⑤ · four-word listening',`<div class="wrap"><span class="tag">CHECK 1⑤ · FOUR WORDS · NO HELP</span><div class="lead">At least 3 first-try answers.</div><div id="check-sounds"></div></div>`,el=>{let deck=[],i=0,count=0,wrong=[];function paint(){if(i>=deck.length){state.check1.sounds={firstTry:count>=3,score:count,total:4,wrong};save();el.querySelector('#check-sounds').innerHTML=`<div class="task-card"><div class="lead">${count} / 4 first-try answers</div><div class="sub">Check 1⑤ recorded. Repair follows only if needed.</div></div>`;return;}choiceTask(el.querySelector('#check-sounds'),TASKS[deck[i]],{label:'Check 1⑤ · '+(i+1)+' / 4',onAnswer:r=>{if(r.correct)count++;else wrong.push(deck[i]);},onNext:()=>{i++;paint();}});}return{onEnter(){deck=shuffle(['soundcape','soundcap','soundpin','soundpine','soundtape','soundtime']).slice(0,4);i=0;count=0;wrong=[];paint();}};});

/* S15 */
addScreen('Repair failed items · Check 2',`<div class="wide"><span class="tag">MEANING → SLOW → CONTRAST → MODEL → BUILD → HIDE HELP → TRY AGAIN</span><div class="lead" id="repair-title">Repair only failed items</div><div class="grid2" style="align-items:start"><div id="repair-visual" class="task-card repair-view"></div><div><div id="repair-copy" class="task-card repair-copy"></div><div class="repair-steps">${['Meaning','Slow','Contrast','Model','Build','Hide help','Try again'].map((t,i)=>`<button class="action secondary repair-step" data-step="${i}">${i+1} ${t}</button>`).join('')}</div></div></div><div class="row" style="margin-top:10px"><button id="repair-next" class="action amber" style="display:none">Repair next failed item</button><button id="to-final" class="action green" disabled>Final Show locked</button></div></div>`,el=>{
  let failed=[],index=0,target=null,nextStep=0;
  const content={chant:{meaning:'happy = سعيد<br>clap your hands = صفّق بيديك',audio:'a_official_chant_clap.mp3',contrast:'E = fifth<br>F = sixth',model:"No, it's the sixth letter.",modelAudio:'a_t_no_sixth.mp3',build:'If you’re → happy → clap your hands<br>No → it’s the → sixth → letter',visual:'l2_chant_girl.jpg'},feelings:{meaning:'What’s the matter? = ما الأمر؟<br>I’m cold. = أنا أشعر بالبرد',audio:'a_official_wtm.mp3',contrast:'Ask: What’s the matter?<br>Answer: I’m cold.',model:"What's the matter? / I'm cold.",modelAudio:'a_official_ans_cold.mp3',build:'What’s → the → matter?<br>I’m → cold',visual:'ft_cold.jpg'},sounds:{meaning:'short a: cap<br>long a_e: cape',audio:'a_t_w_cape.mp3',contrast:'pin = short i<br>pine = long i_e',model:'cape / pine',modelAudio:'a_t_w_pine.mp3',build:'c → a → p → e<br>p → i → n → e',visual:'magic_e.jpg'}};
  function updateFinal(){const ok=finalUnlocked(),b=el.querySelector('#to-final');b.disabled=!ok;b.textContent=ok?'Start Final Show':'Final Show locked';b.onclick=()=>{if(finalUnlocked())show(15);};}
  function resetSteps(){nextStep=0;el.querySelectorAll('.repair-step').forEach(b=>{b.disabled=false;b.classList.remove('done');b.classList.add('secondary');b.onclick=()=>{const step=+b.dataset.step;if(step!==nextStep){toast('Follow the next repair step.');return;}paintStep(step);b.classList.remove('secondary');b.classList.add('done');nextStep++;};});}
  function finishCheck2(independent,detail={}){state.check2[target]={done:true,independent,...detail};save();el.querySelector('#repair-copy').innerHTML+=`<div class="feedback">Check 2 recorded · ${independent?'independent':'more practice needed'}</div>`;if(index<failed.length-1){const n=el.querySelector('#repair-next');n.style.display='inline-block';n.onclick=()=>{index++;n.style.display='none';paintTarget();};}updateFinal();}
  function renderCheck2(){const host=el.querySelector('#repair-copy');if(target==='sounds'){const deck=['soundtape','soundtime','soundcap','soundpine'];let i=0,count=0;function paint(){if(i>=4){host.innerHTML='<div class="mini-label">CHECK 2 COMPLETE</div><div class="lead">'+count+' / 4</div>';finishCheck2(count>=3,{score:count,total:4});return;}choiceTask(host,TASKS[deck[i]],{label:'Check 2 · '+(i+1)+' / 4',onAnswer:r=>{if(r.correct)count++;},onNext:()=>{i++;paint();}});}paint();return;}
    if(target==='chant'){const correction=state.check1.chant.parts&&state.check1.chant.parts.correction===false;teacherObservation(host,{label:'Check 2 · parallel evidence',title:correction?'Fix a new false statement.':'Chant the keywords without a frame.',audio:correction?'a_t_b_first.mp3':'a_official_chant_clap.mp3',caption:correction?'B is the first letter.':'No lyrics on screen.',hint:correction?'No …':"If you're …",onObserve:r=>finishCheck2(r.independent,{helped:r.helped})});return;}
    const ask=state.check1.feelings.parts&&state.check1.feelings.parts.ask===false;teacherObservation(host,{label:'Check 2 · parallel evidence',title:ask?'Ask your teacher again.':'Answer a new picture.',image:ask?'wc2_talk_a.png':'ft_hot.jpg',hint:ask?"What's …":"I'm …",onObserve:r=>finishCheck2(r.independent,{helped:r.helped})});
  }
  function paintStep(step){const c=content[target];stopAudio();el.querySelector('#repair-visual').innerHTML=`<img class="pic" src="${A}${c.visual}" style="max-height:230px;width:100%">`;const copy=el.querySelector('#repair-copy');if(step===0)copy.innerHTML=c.meaning;if(step===1){copy.textContent='Listen slowly. Watch, then repeat.';play(c.audio,null,true);}if(step===2)copy.innerHTML=c.contrast;if(step===3){copy.textContent=c.model;play(c.modelAudio);}if(step===4)copy.innerHTML='<div class="help-flash">'+c.build+'</div>';if(step===5){copy.textContent='No model. No Arabic. Get ready for a parallel item.';el.querySelector('#repair-visual').innerHTML='<div class="lead">Help is hidden.</div>';}if(step===6)renderCheck2();}
  function paintTarget(){target=failed[index];nextStep=0;el.querySelector('#repair-title').textContent='Repair '+(index+1)+' / '+failed.length+': '+({chant:'③ Chant + ordinal',feelings:'④ Feelings',sounds:'⑤ Sounds'}[target]);el.querySelector('#repair-copy').textContent='Start with Meaning. Follow all seven steps.';el.querySelector('#repair-visual').innerHTML=`<img class="pic" src="${A}${content[target].visual}" style="max-height:230px;width:100%">`;resetSteps();updateFinal();}
  return{onEnter(){failed=failedChecks();index=0;el.querySelector('#repair-next').style.display='none';if(!check1Complete()){el.querySelector('#repair-title').textContent='Complete Check 1③–⑤ first';el.querySelector('#repair-copy').textContent='Three Check 1 records are needed.';el.querySelector('#repair-visual').innerHTML='<button id="go-check" class="action">Go to Check 1③</button>';el.querySelector('#go-check').onclick=()=>show(11);el.querySelectorAll('.repair-step').forEach(b=>b.disabled=true);updateFinal();return;}if(!failed.length){el.querySelector('#repair-title').textContent='No failed Check 1 item';el.querySelector('#repair-copy').textContent='No repair is needed. Continue to the Final Show.';el.querySelector('#repair-visual').innerHTML='<div class="lead">Check 1 complete.</div>';el.querySelectorAll('.repair-step').forEach(b=>b.disabled=true);updateFinal();return;}paintTarget();}};
});

/* S16 */
addScreen('Final Show · six continuous challenges',`<div class="wrap"><span class="tag">FINAL SHOW · ANSWERS HIDDEN</span><div class="lead" id="final-title">Six challenges. You star!</div><div id="final-lock"></div><div id="final-task"></div><div id="final-next" class="row"></div></div>`,el=>{
  let i=0;const ids=['talk','ordinal','chant','feelings','sounds','goodbye'];
  const configs={talk:{title:'Five-turn first meeting. Take role B.',hint:"It's … / I'm …",extra:'<div class="row"><button class="action secondary" data-audio="a_official_tt1.mp3">Teacher A1</button><button class="action secondary" data-audio="a_official_tt3.mp3">Teacher A3</button><button class="action secondary" data-audio="a_official_tt5.mp3">Teacher A5</button></div>'},ordinal:{title:'Your place is third. Say the complete sentence.',image:'sec_queue.png',hint:"I'm …"},chant:{title:'Join the clap verse, then fix F.',hint:"If you're … / No …",extra:'<div class="row"><button class="action secondary" data-audio="a_official_chant_clap.mp3">Play chant</button><button class="action secondary" data-audio="a_t_f_seventh.mp3">Play false F</button></div>'},feelings:{title:'Ask your teacher. Then answer from the picture.',image:'ft_cold.jpg',hint:"What's … / I'm …"},goodbye:{title:'End the show with two farewell lines.',hint:'Good-bye …'}};
  function record(id,r){state.final[id]={done:true,independent:r.independent,helped:r.helped};save();const n=document.createElement('button');n.className='action amber';n.textContent=i===5?'Finish Final Show':'Next challenge';n.onclick=()=>{i++;paint();};el.querySelector('#final-next').innerHTML='';el.querySelector('#final-next').appendChild(n);}
  function paintSounds(){const deck=['soundtape','soundpin','soundcap','soundtime'];let q=0,count=0;function one(){if(q>=4){record('sounds',{independent:count>=3,helped:false});el.querySelector('#final-task').innerHTML=`<div class="task-card"><div class="lead">${count} / 4</div><div class="sub">Sound challenge recorded.</div></div>`;return;}choiceTask(el.querySelector('#final-task'),TASKS[deck[q]],{label:'Final ⑤ · '+(q+1)+' / 4',onAnswer:r=>{if(r.correct)count++;},onNext:()=>{q++;one();}});}one();}
  function paint(){stopAudio();el.querySelector('#final-next').innerHTML='';el.querySelector('#final-lock').innerHTML='';if(!finalUnlocked()){el.querySelector('#final-title').textContent='Final Show is locked';el.querySelector('#final-lock').innerHTML='<div class="locked"><div class="task-title">Finish Check 1③–⑤ and every required Check 2 first.</div><button id="final-go-repair" class="action">Go to repair status</button></div>';el.querySelector('#final-task').innerHTML='';el.querySelector('#final-go-repair').onclick=()=>show(14);return;}if(i>=ids.length){const count=Object.values(state.final).filter(x=>x.independent).length;el.querySelector('#final-title').textContent='Final Show complete';el.querySelector('#final-task').innerHTML=`<div class="task-card unlocked"><div class="lead">${count} / 6 independent challenges</div><div class="sub">This counts actual teacher observations and the four-word listening result. It is not a speech score.</div></div>`;sfx('sfx_success.mp3');return;}const id=ids[i];el.querySelector('#final-title').textContent='Challenge '+(i+1)+' / 6 · '+({talk:'Talk',ordinal:'Number',chant:'Chant + correction',feelings:'Feelings',sounds:'Sounds',goodbye:'Good-bye'}[id]);if(id==='sounds'){paintSounds();return;}teacherObservation(el.querySelector('#final-task'),{label:'Final '+(i+1)+' / 6 · no Arabic',...configs[id],onObserve:r=>record(id,r)});}
  return{onEnter(){i=0;paint();}};
});

/* S17 */
addScreen('School interface · feelings',`<div class="wrap"><span class="tag">SCHOOL INTERFACE · LISTEN AND CHOOSE</span><div class="lead">What's the matter?</div><div id="school-feel"></div><div class="school-note">Temporary H5 imitation · pending current 1448 Workbook verification</div></div>`,el=>({onEnter(){choiceTask(el.querySelector('#school-feel'),TASKS.schoolFeel,{label:'School item · no Arabic',next:false,retry:true});}}));

/* S18 */
addScreen('School interface · sound discrimination',`<div class="wrap"><span class="tag">SCHOOL INTERFACE · WHOLE-WORD LISTENING</span><div class="lead">Short or long?</div><div class="row"><button id="sound-group-a" class="action secondary">a / a_e group</button><button id="sound-group-i" class="action secondary">i / i_e group</button></div><div id="school-sound"></div><div class="school-note">Temporary H5 imitation · pending current 1448 Workbook verification</div></div>`,el=>{let group='a';function paint(){const id=group==='a'?'soundcape':'soundpin';choiceTask(el.querySelector('#school-sound'),TASKS[id],{label:'School item · teacher may switch group',next:false,retry:true});el.querySelector('#sound-group-a').classList.toggle('amber',group==='a');el.querySelector('#sound-group-i').classList.toggle('amber',group==='i');}return{onEnter(){const wrong=state.check1.sounds&&state.check1.sounds.wrong||[];group=wrong.some(x=>/pin|pine|time|Tim/.test(x))?'i':'a';el.querySelector('#sound-group-a').onclick=()=>{group='a';paint();};el.querySelector('#sound-group-i').onclick=()=>{group='i';paint();};paint();}};});

/* S19 */
addScreen('Six actual learning records',`<div class="wrap"><span class="tag">ACTUAL FINAL SHOW EVIDENCE · NOT A GRADE</span><div class="lead" id="evidence-lead">What happened today?</div><div class="evidence" id="evidence"></div><div class="sub" style="margin-top:14px">Review includes every challenge type and the items that still need practice.</div></div>`,el=>({onEnter(){const names={talk:'① Five-turn talk',ordinal:'② Given place',chant:'③ Chant + correction',feelings:'④ Ask + answer',sounds:'⑤ Four-word listening',goodbye:'⑥ Good-bye · WC1 transfer'};const rows=Object.entries(names).map(([k,name])=>{const r=state.final[k];const text=!r?'Not done':r.independent?'Independent evidence':r.helped?'Completed with help':'Support needed';return`<div class="task-card"><div class="mini-label">${name}</div><h3>${!r?'Not done':r.independent?'Independent':'Completed / needs practice'}</h3><p>${text}</p></div>`;});el.querySelector('#evidence').innerHTML=rows.join('');const done=Object.keys(state.final).length,count=Object.values(state.final).filter(x=>x.independent).length;el.querySelector('#evidence-lead').textContent=count+' independent · '+done+' / 6 recorded';save();}}));

/* S20 */
addScreen('Exit · voluntary home show + Review',`<div class="wide grid2" style="grid-template-columns:1.25fr .75fr;align-items:center"><div class="task-card"><span class="tag">HOME SHOW · VOLUNTARY</span><div class="lead">Show your family!</div><div class="frame">Choose any challenges you enjoy.<br>A 30-second family video is optional.</div><div class="sub" style="margin-top:16px">No classroom recording is required. Review has four short stations.</div><div class="audio-line"><button class="speaker" data-audio="a_t_goodbye_seeyou.mp3"></button><div class="caption">Good-bye. See you.</div></div></div><div class="task-card" style="text-align:center"><div class="task-title">Home Review</div><img src="${A}sec_qr_review.png" alt="Home review QR" style="width:190px;height:190px;object-fit:contain;background:#fff"><a href="review/" target="_blank" class="action green" style="display:inline-block;text-decoration:none;margin-top:10px">Open four-station Review</a><div class="sub" style="margin-top:12px;font-size:15px">Scan the code or tap the button.</div><div class="ar" style="font-size:15px;color:#6f6680">امسح الرمز أو اضغط الزر</div></div></div>`);

(function(){const th=$('#thumbs');screens.forEach((s,k)=>{const b=document.createElement('button');b.dataset.page=k;b.textContent=(k+1)+' · '+s.objective;b.onclick=()=>{show(k);th.classList.remove('open');};th.appendChild(b);});const reset=document.createElement('button');reset.id='new-class';reset.textContent='Start a new class';reset.onclick=()=>{try{const old=localStorage.getItem(STORE);if(old){const history=readJSON('khusoosi:'+LESSON_KEY+':history',[]);history.push({savedAt:new Date().toISOString(),progress:JSON.parse(old)});localStorage.setItem('khusoosi:'+LESSON_KEY+':history',JSON.stringify(history.slice(-10)));}localStorage.removeItem(STORE);}catch(e){}location.href=location.pathname+'?p=1';};th.appendChild(reset);})();
const query=new URLSearchParams(location.search);const p0=parseInt(query.get('p')||'1',10);if(query.get('ar')){document.body.classList.add('ar-on');$('#btn-ar').setAttribute('aria-pressed','true');}if(query.get('teacher')){document.body.classList.add('teacher-on');$('#btn-teacher').setAttribute('aria-pressed','true');}
fit();show(Number.isNaN(p0)?0:p0-1);
